import { EMPTY_ARR, IS_NON_DIMENSIONAL } from '../constants';
import options from '../options';

/**
 * Reuse a DOM node from the list of excess children when it matches the vnode.
 * @param {import('../internal').PreactElement} dom
 * @param {import('../internal').VNode} vnode
 * @param {Array<import('../internal').PreactElement>} excessDomChildren
 * @returns {import('../internal').PreactElement}
 */
export function matchExcessChild(dom, vnode, excessDomChildren) {
	if (excessDomChildren != null) {
		for (let i = 0; i < excessDomChildren.length; i++) {
			const child = excessDomChildren[i];

			// if vnode matches an element in excessDomChildren or the `dom`
			// argument matches an element in excessDomChildren, remove it from
			// excessDomChildren so it isn't later removed in diffChildren
			if (
				child != null &&
				((vnode.type === null
					? child.nodeType === 3
					: child.localName === vnode.type) ||
					dom == child)
			) {
				excessDomChildren[i] = null;
				return child;
			}
		}
	}
	return dom;
}

/**
 * Snapshot a host node's children and, when requested, its attributes.
 * @param {import('../internal').PreactElement} dom
 * @param {boolean} recordAttrs
 */
export function captureHostState(dom, recordAttrs) {
	let oldProps;
	if (recordAttrs) {
		oldProps = {};
		for (let i = 0; i < dom.attributes.length; i++) {
			oldProps[dom.attributes[i].name] = dom.attributes[i].value;
		}
	}
	return {
		children: EMPTY_ARR.slice.call(dom.childNodes),
		props: oldProps
	};
}

/**
 * Diff the old and new properties of a VNode and apply changes to the DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to apply
 * changes to
 * @param {object} newProps The new props
 * @param {object} oldProps The old props
 * @param {boolean} isSvg Whether or not this node is an SVG node
 * @param {boolean} hydrate Whether or not we are in hydration mode
 */
export function diffProps(dom, newProps, oldProps, isSvg, hydrate) {
	let i;

	for (i in oldProps) {
		if (i !== 'children' && i !== 'key' && !(i in newProps)) {
			setProperty(dom, i, null, oldProps[i], isSvg);
		}
	}

	for (i in newProps) {
		if (
			(!hydrate || typeof newProps[i] == 'function') &&
			i !== 'children' &&
			i !== 'key' &&
			i !== 'value' &&
			i !== 'checked' &&
			oldProps[i] !== newProps[i]
